"}

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#edifact-invoic-ontology> a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A deeply structured OWL2 ontology for D96A EANCOM INVOIC messages, supporting full segment and qualifier coverage, party roles, and regulatory alignment." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level UN/EDIFACT interchange envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message container." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message as defined in UN/EDIFACT D96A." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "Generic EDIFACT segment (BGM, NAD, DTM, etc.)." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGMSegment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NADSegment" ;
    rdfs:comment "Name and Address segment for participant details." .

:DTM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTMSegment" ;
    rdfs:comment "Date/Time/Period segment (e.g., Document Date, Invoice Date)." .

:MOA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOASegment" ;
    rdfs:comment "Monetary Amount segment (e.g., invoice totals, line item amounts)." .

:TAX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAXSegment" ;
    rdfs:comment "Tax information segment (rates, amounts, types)." .

:QTY_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTYSegment" ;
    rdfs:comment "Quantity segment (e.g., line item quantities)." .

:RFF_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "RFFSegment" ;
    rdfs:comment "Reference segment (e.g., Invoice Number, Order Number, VAT/Fiscal Reference)." .

:LIN_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LINSegment" ;
    rdfs:comment "Line Item segment for item identification." .

:PIA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PIASegment" ;
    rdfs:comment "Additional Product Id segment for item reference alternatives." .

:IMD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "IMDSegment" ;
    rdfs:comment "Item Description segment for item characteristics." .

:ALC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALCSegment" ;
    rdfs:comment "Allowance/Charge segment for discounts, surcharges, etc." .

:ALC_Detail_Group a owl:Class ;
    rdfs:label "ALCDetailGroup" ;
    rdfs:comment "Group for associating ALC with PCD, MOA, TAX segments for calculation basis." .

:UNS_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNSSegment" ;
    rdfs:comment "Section Control segment for header/detail/summary separation." .

:CNT_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CNTSegment" ;
    rdfs:comment "Control segment for document totals and counts." .

:PAC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PACSegment" ;
    rdfs:comment "Packaging segment for number and type of packages shipped." .

:PCD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PCDSegment" ;
    rdfs:comment "Percentage Details segment for allowance/charge calculations." .

:TOD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TODSegment" ;
    rdfs:comment "Terms of Delivery or Transport segment." .

:CUX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CUXSegment" ;
    rdfs:comment "Currency segment for document and line-level currency codes." .

:FTX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "FTXSegment" ;
    rdfs:comment "Free Text segment for additional information." .

:LOC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LOCSegment" ;
    rdfs:comment "Location segment for places related to delivery, dispatch, etc." .

:MEA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MEASegment" ;
    rdfs:comment "Measurement segment for weights, dimensions, etc." .

:PRI_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PRISegment" ;
    rdfs:comment "Price Details segment for price types and values." .

:HeaderSection a owl:Class ;
    rdfs:label "HeaderSection" ;
    rdfs:comment "Section containing header-level segments and references." .

:DetailSection a owl:Class ;
    rdfs:label "DetailSection" ;
    rdfs:comment "Section containing line items and associated segments." .

:SummarySection a owl:Class ;
    rdfs:label "SummarySection" ;
    rdfs:comment "Section containing summary-level amounts, taxes, and controls." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "Business entity involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "AgentRole" ;
    rdfs:comment "Role played by an organization in a transaction (buyer, supplier, etc.)." .

:BuyerRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "BuyerRole" ;
    rdfs:comment "Role of buyer in the invoice." .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "DeliveryPartyRole" ;
    rdfs:comment "Role of delivery party in the invoice." .

:Warehouse a owl:Class ;
    rdfs:label "Warehouse" ;
    rdfs:comment "Warehouse location associated with an organization." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Postal address for an organization or warehouse." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "GlobalLocationNumber" ;
    rdfs:comment "GLN identifier for organizations and locations." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "Product or service sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Net price or unit price of an item." .

:InvoiceAmount a owl:Class ;
    rdfs:label "InvoiceAmount" ;
    rdfs:comment "Total amount of the invoice." .

:InvoiceNumber a owl:Class ;
    rdfs:label "InvoiceNumber" ;
    rdfs:comment "Unique identifier for the invoice document." .

:BusinessProcess a owl:Class ;
    rdfs:label "BusinessProcess" ;
    rdfs:comment "Business process associated with the invoice (e.g., procurement)." .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACLConstraint" ;
    rdfs:comment "SHACL shape for automated validation of the invoice." .

:EN16931Alignment a owl:Class ;
    rdfs:label "EN16931Alignment" ;
    rdfs:comment "Alignment with the European e-Invoicing Standard EN 16931-1." .

:P2P_O_Alignment a owl:Class ;
    rdfs:label "P2POAlignment" ;
    rdfs:comment "Alignment with the Purchase-to-Pay Ontology (P2P-O)." .

:LineItem a owl:Class ;
    rdfs:label "LineItem" ;
    rdfs:comment "Individual line item in the invoice detail section." .

:ReferenceNumber a owl:Class ;
    rdfs:label "ReferenceNumber" ;
    rdfs:comment "Generic reference number (invoice, order, etc.)." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "OrganizationRoleAssignment" ;
    rdfs:comment "Pivot class for associating organizations with roles in a transaction." .

:CompositeDataElement a owl:Class ;
    rdfs:label "CompositeDataElement" ;
    rdfs:comment "EDIFACT composite data element grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "SimpleDataElement" ;
    rdfs:comment "EDIFACT simple data element." .

#################################################################
# Disjointness
#################################################################
:Organization owl:disjointWith :AgentRole, :Segment, :Item, :Address, :Price, :InvoiceAmount, :InvoiceNumber, :BusinessProcess .
:AgentRole owl:disjointWith :Segment, :Item, :Address, :Price, :InvoiceAmount, :InvoiceNumber, :BusinessProcess .
:Segment owl:disjointWith :Item, :Address, :Price, :InvoiceAmount, :InvoiceNumber, :BusinessProcess .

#################################################################
# DisjointUnion
#################################################################
:AgentRole owl:disjointUnionOf (:BuyerRole :DeliveryPartyRole) .

#################################################################
# Properties
#################################################################
:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "containsMessage" ;
    rdfs:comment "Envelope contains one or more messages." .
:containsMessage owl:inverseOf :isContainedInEnvelope .
:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "isContainedInEnvelope" ;
    rdfs:comment "Message is contained in envelope." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "hasSegment" ;
    rdfs:comment "Message has segment (BGM, NAD, etc.)." .
:hasSegment owl:inverseOf :isSegmentOf .
:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "isSegmentOf" ;
    rdfs:comment "Segment is part of a message." .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    rdfs:label "hasHeader" ;
    rdfs:comment "Invoice message has header section." .
:hasHeader owl:inverseOf :isHeaderOf .
:isHeaderOf a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "isHeaderOf" ;
    rdfs:comment "Header section belongs to invoice message." .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    rdfs:label "hasDetail" ;
    rdfs:comment "Invoice message has detail section." .
:hasDetail owl:inverseOf :isDetailOf .
:isDetailOf a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "isDetailOf" ;
    rdfs:comment "Detail section belongs to invoice message." .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "hasSummary" ;
    rdfs:comment "Invoice message has summary section." .
:hasSummary owl:inverseOf :isSummaryOf .
:isSummaryOf a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "isSummaryOf" ;
    rdfs:comment "Summary section belongs to invoice message." .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "hasLineItem" ;
    rdfs:comment "Detail section has line item." .
:hasLineItem owl:inverseOf :isLineItemOf .
:isLineItemOf a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "isLineItemOf" ;
    rdfs:comment "Line item is part of detail section." .

:describesItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describesItem" ;
    rdfs:comment "Line item describes a product or service." .
:describesItem owl:inverseOf :isDescribedByLineItem .
:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "isDescribedByLineItem" ;
    rdfs:comment "Item is described by a line item." .

:hasNetPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "hasNetPrice" ;
    rdfs:comment "Line item has net price." .
:hasNetPrice owl:inverseOf :isNetPriceOf .
:isNetPriceOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "isNetPriceOf" ;
    rdfs:comment "Price is net price of a line item." .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "hasQuantity" ;
    rdfs:comment "Quantity of item in line item." .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    rdfs:label "hasInvoiceAmount" ;
    rdfs:comment "Summary section has invoice total amount." .
:hasInvoiceAmount owl:inverseOf :isInvoiceAmountOf .
:isInvoiceAmountOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    rdfs:label "isInvoiceAmountOf" ;
    rdfs:comment "Invoice amount is part of summary section." .

:hasInvoiceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceNumber ;
    rdfs:label "hasInvoiceNumber" ;
    rdfs:comment "Header section has invoice number." .
:hasInvoiceNumber owl:inverseOf :isInvoiceNumberOf .
:isInvoiceNumberOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceNumber ;
    rdfs:range :HeaderSection ;
    rdfs:label "isInvoiceNumberOf" ;
    rdfs:comment "Invoice number is part of header section." .

:hasReferenceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber ;
    rdfs:label "hasReferenceNumber" ;
    rdfs:comment "Header section has reference number (order, delivery note, etc.)." .
:hasReferenceNumber owl:inverseOf :isReferenceNumberOf .
:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :HeaderSection ;
    rdfs:label "isReferenceNumberOf" ;
    rdfs:comment "Reference number is part of header section." .

:hasOrganizationRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "hasOrganizationRoleAssignment" ;
    rdfs:comment "Invoice message links to organization-role assignments." .
:hasOrganizationRoleAssignment owl:inverseOf :isOrganizationRoleAssignmentOf .
:isOrganizationRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "isOrganizationRoleAssignmentOf" ;
    rdfs:comment "Organization role assignment is part of invoice message." .

:involvesOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "involvesOrganization" ;
    rdfs:comment "Role assignment involves an organization." .
:involvesOrganization owl:inverseOf :isOrganizationInRoleAssignment .
:isOrganizationInRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "isOrganizationInRoleAssignment" ;
    rdfs:comment "Organization is involved in role assignment." .

:hasAgentRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "hasAgentRole" ;
    rdfs:comment "Role assignment specifies the agent role (buyer, delivery party, etc.)." .
:hasAgentRole owl:inverseOf :isAgentRoleOf .
:isAgentRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
