:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "Generic EDIFACT segment (BGM, NAD, DTM, etc.)." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:DTM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment (e.g., Document Date, Invoice Date)." .

:MOA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment (e.g., invoice totals, line item amounts)." .

:TAX_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax information segment (rates, amounts, types)." .

:QTY_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment (e.g., line item quantities)." .

:RFF_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment (e.g., Invoice Number, Order Number, VAT/Fiscal Reference)." .

:LIN_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment for item identification." .

:PIA_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PIA Segment" ;
    rdfs:comment "Additional Product Id segment for item reference alternatives." .

:IMD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "IMD Segment" ;
    rdfs:comment "Item Description segment for item characteristics." .

:ALC_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowance/Charge segment for discounts, surcharges, etc." .

:ALC_Detail_Group a owl:Class ;
    rdfs:label "Allowance/Charge Detail Group" ;
    rdfs:comment "Group for associating ALC with PCD, MOA, TAX segments for calculation basis." .

:UNS_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section Control segment for header/detail/summary separation." .

:CNT_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "CNT Segment" ;
