@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing EDIFACT invoice messages, segments, roles, and validation constraints, aligned with D96A and EN 16931-1." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The envelope that contains one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice, such as INVOIC." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment, used for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, used for participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a segment." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section of the invoice containing document dates and reference numbers." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section of the invoice containing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section of the invoice containing totals and tax information." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the transaction (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., buyer, seller, delivery party)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A reified relationship assigning a specific AgentRole to an Organization within an InvoiceMessage." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:LocationIdentifier a owl:Class ;
    rdfs:label "Location Identifier" ;
    rdfs:comment "A unique identifier for an organization location (e.g., GLN)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service described in the invoice." .

:ItemLine a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Item Line" ;
    rdfs:comment "A line in the invoice detail section describing an item, its quantity, and price." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice or item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number such as invoice number or document reference." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint (e.g., SHACL) for validating invoice data completeness and correctness." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an envelope to the message(s) it contains." ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a message to its segments." .

:hasHeader a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header" ;
    rdfs:comment "Relates an invoice message to its header section." ;
    owl:FunctionalProperty .

:hasDetail a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail" ;
    rdfs:comment "Relates an invoice message to its detail section." ;
    owl:FunctionalProperty .

:hasSummary a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary" ;
    rdfs:comment "Relates an invoice message to its summary section." ;
    owl:FunctionalProperty .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an invoice message to a role assignment (pivot class)." .

:assignedRole a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "The agent role assigned in a role assignment." ;
    owl:FunctionalProperty .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "The organization involved in a role assignment." ;
    owl:FunctionalProperty .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Associates an organization with its address." .

:hasLocationIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :LocationIdentifier ;
    rdfs:label "has location identifier" ;
    rdfs:comment "Associates an organization with its GLN or other identifier." ;
    owl:FunctionalProperty .

:buyerRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "buyer role of" ;
    rdfs:comment "Indicates that this agent role is that of a buyer for a message." .

:deliveryPartyRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "delivery party role of" ;
    rdfs:comment "Indicates that this agent role is that of a delivery party for a message." .

:hasItemLine a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :ItemLine ;
    rdfs:label "has item line" ;
    rdfs:comment "Links the detail section to its item lines." .

:referencesItem a owl:ObjectProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :Item ;
    rdfs:label "references item" ;
    rdfs:comment "Indicates which item is described by this item line." ;
    owl:FunctionalProperty .

:hasPrice a owl:ObjectProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Links an item line to its price." ;
    owl:FunctionalProperty .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links the summary section to tax details." .

:hasReferenceNumber a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links the header section to a reference number (e.g., invoice number)." ;
    owl:FunctionalProperty .

:assignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned to business process" ;
    rdfs:comment "Assigns the invoice message to a business process." ;
    owl:FunctionalProperty .

#################################################################
# Data Properties
#################################################################

:documentDate a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "document date" ;
    rdfs:comment "The date of the document (string for extensibility)." ;
    owl:FunctionalProperty .

:netPrice a owl:DatatypeProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "net price" ;
    rdfs:comment "Net price of the item." ;
    owl:FunctionalProperty .

:quantity a owl:DatatypeProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range xsd:decimal ;
    rdfs:label "quantity" ;
    rdfs:comment "Quantity of the item in the item line." ;
    owl:FunctionalProperty .

:invoiceAmount a owl:DatatypeProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "Total amount of the invoice." ;
    owl:FunctionalProperty .

:taxAmount a owl:DatatypeProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "Amount of tax." ;
    owl:FunctionalProperty .

:invoiceNumber a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The invoice number." ;
    owl:FunctionalProperty .

:organizationName a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "organization name" ;
    rdfs:comment "Name of the organization." ;
    owl:FunctionalProperty .

:addressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "Street and number of the address." ;
    owl:FunctionalProperty .

:postalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "Postal code of the address." ;
    owl:FunctionalProperty .

:city a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "City of the address." ;
    owl:FunctionalProperty .

:countryCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country code" ;
    rdfs:comment "Country code of the address." ;
    owl:FunctionalProperty .

:locationIdentifierValue a owl:DatatypeProperty ;
    rdfs:domain :LocationIdentifier ;
    rdfs:range xsd:string ;
    rdfs:label "location identifier value" ;
    rdfs:comment "The value of the location identifier (e.g., GLN)." ;
    owl:FunctionalProperty .

:itemDescription a owl:DatatypeProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "item description" ;
    rdfs:comment "Description of the item." ;
    owl:FunctionalProperty .

:referenceValue a owl:DatatypeProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "reference value" ;
    rdfs:comment "Value of the reference number (e.g., invoice number)." ;
    owl:FunctionalProperty .

:constraintDescription a owl:DatatypeProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range xsd:string ;
    rdfs:label "constraint description" ;
    rdfs:comment "Description of the validation constraint (e.g., SHACL rule)." ;
    owl:FunctionalProperty .

#################################################################
# Class Disjointness
#################################################################

:Organization owl:disjointWith :Item, :Address, :ItemLine, :AgentRole .
:InvoiceMessage owl:disjointWith :Organization, :ItemLine .
:RoleAssignment owl:disjointWith :Organization, :AgentRole, :Address .
:Segment owl:disjointUnionOf (:BGM_Segment :NAD_Segment) .

