    rdfs:label "Item Line" ;
    rdfs:comment "A line in the invoice detail section describing an item, its quantity, and price." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice or item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number such as invoice number or document reference." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

