    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a message to its segments." .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of message" ;
    rdfs:comment "Relates a segment to the message it is part of. Inverse of hasSegment." ;
    owl:inverseOf :hasSegment .

:hasHeader a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header" ;
    rdfs:comment "Relates an invoice message to its header section." .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is header of invoice message" ;
    rdfs:comment "Relates a header section to the invoice message it is part of. Inverse of hasHeader." ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail" ;
    rdfs:comment "Relates an invoice message to its detail section." .

:isDetailOf a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is detail of invoice message" ;
    rdfs:comment "Relates a detail section to the invoice message it is part of. Inverse of hasDetail." ;
    owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary" ;
    rdfs:comment "Relates an invoice message to its summary section." .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is summary of invoice message" ;
    rdfs:comment "Relates a summary section to the invoice message it is part of. Inverse of hasSummary." ;
    owl:inverseOf :hasSummary .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an invoice message to a role assignment (pivot class)." .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is role assignment of invoice message" ;
    rdfs:comment "Relates a role assignment to the invoice message it is part of. Inverse of hasRoleAssignment." ;
    owl:inverseOf :hasRoleAssignment .

:assignedRole a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "The agent role assigned in a role assignment." .

:isAssignedRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is assigned role of role assignment" ;
    rdfs:comment "Relates an agent role to the role assignment it is assigned to. Inverse of assignedRole." ;
    owl:inverseOf :assignedRole .

:involvesOrganization a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "The organization involved in a role assignment." .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is organization involved in role assignment" ;
    rdfs:comment "Relates an organization to the role assignment it is involved in. Inverse of involvesOrganization." ;
    owl:inverseOf :involvesOrganization .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Associates an organization with its address." .

:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Relates an address to the organization it belongs to. Inverse of hasAddress." ;
    owl:inverseOf :hasAddress .

:hasLocationIdentifier a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :LocationIdentifier ;
    rdfs:label "has location identifier" ;
    rdfs:comment "Associates an organization with its GLN or other identifier." .

:isLocationIdentifierOf a owl:ObjectProperty ;
    rdfs:domain :LocationIdentifier ;
    rdfs:range :Organization ;
    rdfs:label "is location identifier of organization" ;
    rdfs:comment "Relates a location identifier to the organization it identifies. Inverse of hasLocationIdentifier." ;
    owl:inverseOf :hasLocationIdentifier .

:buyerRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "buyer role of invoice message" ;
    rdfs:comment "Indicates that this agent role is that of a buyer for a message." .

:hasBuyerRole a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AgentRole ;
    rdfs:label "has buyer role" ;
    rdfs:comment "Relates an invoice message to its buyer role (inverse of buyerRoleOf)." ;
    owl:inverseOf :buyerRoleOf .

:deliveryPartyRoleOf a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "delivery party role of invoice message" ;
    rdfs:comment "Indicates that this agent role is that of a delivery party for a message." .

:hasDeliveryPartyRole a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :AgentRole ;
    rdfs:label "has delivery party role" ;
    rdfs:comment "Relates an invoice message to its delivery party role (inverse of deliveryPartyRoleOf)." ;
    owl:inverseOf :deliveryPartyRoleOf .

:hasItemLine a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :ItemLine ;
    rdfs:label "has item line" ;
    rdfs:comment "Links the detail section to its item lines." .

:isItemLineOf a owl:ObjectProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :DetailSection ;
    rdfs:label "is item line of detail section" ;
    rdfs:comment "Relates an item line to the detail section it is part of. Inverse of hasItemLine." ;
    owl:inverseOf :hasItemLine .

:referencesItem a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :Item ;
    rdfs:label "references item" ;
    rdfs:comment "Indicates which item is described by this item line." .

:isReferencedItemOf a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :ItemLine ;
    rdfs:label "is referenced item of item line" ;
    rdfs:comment "Relates an item to the item line that references it. Inverse of referencesItem." ;
    owl:inverseOf :referencesItem .

:hasPrice a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Links an item line to its price." .

:isPriceOf a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :ItemLine ;
    rdfs:label "is price of item line" ;
    rdfs:comment "Relates a price to the item line it is associated with. Inverse of hasPrice." ;
    owl:inverseOf :hasPrice .

