    rdfs:comment "Links the header section to a reference number (e.g., invoice number)." .

:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :HeaderSection ;
    rdfs:label "is reference number of header section" ;
    rdfs:comment "Relates a reference number to the header section it is associated with. Inverse of hasReferenceNumber." ;
