#################################################################
# Data Properties
#################################################################

:documentDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "document date" ;
    rdfs:comment "The date of the document (string for extensibility)." .

:netPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "net price" ;
    rdfs:comment "Net price of the item." .

:quantity a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :ItemLine ;
    rdfs:range xsd:decimal ;
    rdfs:label "quantity" ;
    rdfs:comment "Quantity of the item in the item line." .

:invoiceAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "Total amount of the invoice." .

:taxAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "Amount of tax." .

:invoiceNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The invoice number." .

:organizationName a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "organization name" ;
    rdfs:comment "Name of the organization." .

:addressLine a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "Street and number of the address." .

:postalCode a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "Postal code of the address." .

:city a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "City of the address." .

:countryCode a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country code" ;
    rdfs:comment "Country code of the address." .

:locationIdentifierValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :LocationIdentifier ;
    rdfs:range xsd:string ;
    rdfs:label "location identifier value" ;
    rdfs:comment "The value of the location identifier (e.g., GLN)." .

:itemDescription a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "item description" ;
    rdfs:comment "Description of the item." .

:referenceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "reference value" ;
    rdfs:comment "Value of the reference number (e.g., invoice number)." .

:constraintDescription a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range xsd:string ;
    rdfs:label "constraint description" ;
    rdfs:comment "Description of the validation constraint (e.g., SHACL rule)." .

#################################################################
# Class Disjointness
#################################################################

:Organization owl:disjointWith :Item, :Address, :ItemLine, :AgentRole .
:InvoiceMessage owl:disjointWith :Organization, :ItemLine .
:RoleAssignment owl:disjointWith :Organization, :AgentRole, :Address .
:Segment owl:disjointUnionOf (:BGM_Segment :NAD_Segment) .

