@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing EDIFACT invoice messages, segments, roles, and validation constraints, aligned with D96A and EN 16931-1." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The envelope that contains one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice, such as INVOIC." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGM_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment, used for document identification." .

:NAD_Segment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, used for participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment. Parent of HeaderSection, DetailSection, SummarySection, ItemLine." ;
    rdfs:seeAlso :HeaderSection, :DetailSection, :SummarySection, :ItemLine .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in a segment. Used as a component of CompositeDataElement." ;
    rdfs:seeAlso :CompositeDataElement .

:hasSimpleDataElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple data element" ;
    rdfs:comment "Relates a composite data element to its simple data elements." .

:isSimpleDataElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple data element of" ;
    rdfs:comment "Inverse of hasSimpleDataElement." ;
    owl:inverseOf :hasSimpleDataElement .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section of the invoice containing document dates and reference numbers." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section of the invoice containing line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section of the invoice containing totals and tax information." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the transaction (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., buyer, seller, delivery party)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A reified relationship assigning a specific AgentRole to an Organization within an InvoiceMessage." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:LocationIdentifier a owl:Class ;
    rdfs:label "Location Identifier" ;
    rdfs:comment "A unique identifier for an organization location (e.g., GLN)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service described in the invoice." .

:ItemLine a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Item Line" ;
    rdfs:comment "A line in the invoice detail section describing an item, its quantity, and price." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice or item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number such as invoice number or document reference." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint (e.g., SHACL) for validating invoice data completeness and correctness." .

