@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/storyid> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Deep Ontology" ;
    rdfs:comment "A deeply structured ontology for UN/EDIFACT INVOIC messages, supporting D96A/EANCOM, EN 16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope containing one or more messages as per EDIFACT structure." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message container." .

:INVOICMessage a owl:Class ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "Specific message type for invoices in EDIFACT." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment, grouping simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple, atomic data element in a composite element." .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "A business invoice as represented in an INVOIC message." .

:InvoiceHeader a owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of an invoice, containing dates and references." ;
    rdfs:subClassOf :CompositeDataElement .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section of an invoice, listing line items." ;
    rdfs:subClassOf :CompositeDataElement .

:InvoiceSummary a owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section of an invoice, providing totals." ;
    rdfs:subClassOf :CompositeDataElement .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An individual line item in the invoice." ;
    rdfs:subClassOf :CompositeDataElement .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in a transaction (e.g., Buyer, Supplier)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Physical or logical address of an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "Generic identifier for organizations or documents." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN as a specific identifier for organizations." ;
    rdfs:subClassOf :Identifier .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A process to which an invoice may be assigned." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price details for a line item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information in an invoice summary." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Reference number for documents or transactions." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item or product sold in an invoice." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reified relation assigning a role to an organization in the context of an invoice." .

#################################################################
# Object Properties and Inverses
#################################################################
:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage: Message is contained in an InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment: Segment is part of a Message." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a Segment to its Composite Data Elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement: CompositeDataElement is part of a Segment." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a Composite Data Element to its Simple Data Elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement: SimpleDataElement is part of a CompositeDataElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

:representsInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "represents invoice" ;
    rdfs:comment "Links an INVOICMessage to the Invoice it describes." ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Invoice ;
    owl:inverseOf :isRepresentedByMessage .

:isRepresentedByMessage a owl:ObjectProperty ;
    rdfs:label "is represented by message" ;
    rdfs:comment "Inverse of representsInvoice: Invoice is described by an INVOICMessage." ;
    rdfs:domain :Invoice ;
    rdfs:range :INVOICMessage ;
    owl:inverseOf :representsInvoice .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links an Invoice to its Header section." ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:label "is header of" ;
    rdfs:comment "Inverse of hasHeader: InvoiceHeader is a header for an Invoice." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an Invoice to its Detail section." ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :isDetailOf .

:isDetailOf a owl:ObjectProperty ;
    rdfs:label "is detail of" ;
    rdfs:comment "Inverse of hasDetail: InvoiceDetail is a detail for an Invoice." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an Invoice to its Summary section." ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :isSummaryOf .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:label "is summary of" ;
    rdfs:comment "Inverse of hasSummary: InvoiceSummary is a summary for an Invoice." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasSummary .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links an InvoiceDetail to its LineItems." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem: LineItem is part of an InvoiceDetail." ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :hasLineItem .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an Invoice to an OrganizationRoleAssignment (pivot for reified roles)." ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization: OrganizationRoleAssignment is involved in an Invoice." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Invoice ;
    owl:inverseOf :involvesOrganization .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has role" ;
    rdfs:comment "Links an OrganizationRoleAssignment to an AgentRole." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse of hasRole: AgentRole is assigned to an OrganizationRoleAssignment." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :hasRole .

:isRoleOf a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "is role of" ;
    rdfs:comment "Links an OrganizationRoleAssignment to an Organization." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasRoleAssignment .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Inverse of isRoleOf: Organization has a role assignment." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :isRoleOf .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse of hasAddress: Address is for an Organization." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifier(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:label "is identifier of" ;
    rdfs:comment "Inverse of hasIdentifier: Identifier identifies an Organization." ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    owl:inverseOf :hasIdentifier .

:hasGlobalLocationNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "Links an Organization to its GLN." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    owl:inverseOf :isGlobalLocationNumberOf .

:isGlobalLocationNumberOf a owl:ObjectProperty ;
    rdfs:label "is Global Location Number of" ;
    rdfs:comment "Inverse of hasGlobalLocationNumber: GlobalLocationNumber is for an Organization." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    owl:inverseOf :hasGlobalLocationNumber .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Links a LineItem to the Item being sold." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:inverseOf :isItemOf .

:isItemOf a owl:ObjectProperty ;
    rdfs:label "is item of" ;
    rdfs:comment "Inverse of hasItem: Item is part of a LineItem." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasItem .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Links a LineItem to its Price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
    rdfs:label "is price of" ;
    rdfs:comment "Inverse of hasPrice: Price is for a LineItem." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasPrice .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an InvoiceSummary to its Tax information." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax ;
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:label "is tax of" ;
    rdfs:comment "Inverse of hasTax: Tax is part of an InvoiceSummary." ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :hasTax .

:assignedToProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Links an Invoice to a BusinessProcess." ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isProcessAssignmentFor .

:isProcessAssignmentFor a owl:ObjectProperty ;
    rdfs:label "is process assignment for" ;
    rdfs:comment "Inverse of assignedToProcess: BusinessProcess is assigned for an Invoice." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :Invoice ;
    owl:inverseOf :assignedToProcess .

#################################################################
# Data Properties
#################################################################
:documentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "document date" ;
    rdfs:comment "The date the document was issued (as string for OWL2 DL compliance)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:referenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "reference number" ;
    rdfs:comment "A reference number for the document." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "invoice number" ;
    rdfs:comment "The official invoice number." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:netPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "net price" ;
    rdfs:comment "Net price for a line item." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal .

:quantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "quantity" ;
    rdfs:comment "Quantity of items in a line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "tax amount" ;
    rdfs:comment "Total tax amount in the invoice summary." ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal .

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "invoice amount" ;
    rdfs:comment "Total invoice amount in the summary." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

:addressLine a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "address line" ;
    rdfs:comment "Address line(s) of an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:organizationName a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "organization name" ;
    rdfs:comment "Name of the organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

#################################################################
# Class Hierarchies and Disjointness
#################################################################
:Segment owl:disjointWith :CompositeDataElement .
:Organization owl:disjointWith :Address .
:InvoiceHeader owl:disjointWith :InvoiceDetail, :InvoiceSummary .
:InvoiceDetail owl:disjointWith :InvoiceSummary .

#################################################################
# Complex Axioms
#################################################################
:INVOICMessage owl:equivalentClass [ a owl:Class ; owl:Restriction [ owl:onProperty :representsInvoice ; owl:allValuesFrom :Invoice ] ] .
:OrganizationRoleAssignment owl:equivalentClass [ a owl:Class ; owl:Restriction [ owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ] ] .

