#################################################################
# HIERARCHY & DISJOINTNESS
#################################################################
:Organization owl:disjointWith :Item, :Invoice .
:Segment owl:disjointWith :CompositeDataElement .
:AgentRole owl:disjointWith :Address .
:AgentRole owl:disjointUnionOf ( :BuyerRole :DeliveryPartyRole ) .
:HeadquartersAddress owl:disjointWith :WarehouseAddress .

#################################################################
# RESTRICTIONS, GCAs, & VALIDATION CONSTRAINTS
#################################################################
# Organization must have at least one GLN, one headquarters address, and legal identifier
:Organization rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :hasGLN ; owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass :GLNIdentifier ],
    [ a owl:Restriction ; owl:onProperty :hasHeadquartersAddress ; owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass :HeadquartersAddress ],
    [ a owl:Restriction ; owl:onProperty :hasLegalIdentifier ; owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass :LegalIdentifier ] .

# InvoiceHeader must have invoice number and document date
:InvoiceHeader rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :hasInvoiceNumber ; owl:minCardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :hasDocumentDate ; owl:minCardinality "1"^^xsd:nonNegativeInteger ] .

# Invoice must involve at least one BuyerRole and one DeliveryPartyRole (GCA)
:Invoice rdfs:subClassOf
    [ a owl:Restriction ;
      owl:onProperty :involvesOrganization ;
      owl:someValuesFrom [
        a owl:Class ;
        owl:intersectionOf (
            :OrganizationRoleAssignment
            [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :BuyerRole ]
        )
      ]
    ],
    [ a owl:Restriction ;
      owl:onProperty :involvesOrganization ;
      owl:someValuesFrom [
        a owl:Class ;
        owl:intersectionOf (
            :OrganizationRoleAssignment
            [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :DeliveryPartyRole ]
        )
      ]
    ] .

# OrganizationRoleAssignment equivalence (unchanged)
:OrganizationRoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      [ a owl:Restriction ; owl:onProperty :assignedOrganization ; owl:someValuesFrom :Organization ]
      [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :AgentRole ]
    )
] .

# Invoice equivalence (unchanged, but now all restrictions above are also inherited)
:Invoice owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      [ a owl:Restriction ; owl:onProperty :involvesOrganization ; owl:someValuesFrom :OrganizationRoleAssignment ]
      [ a owl:Restriction ; owl:onProperty :assignedToBusinessProcess ; owl:someValuesFrom :BusinessProcess ]
    )
] .

